CREATE TABLE prediction_explanation(explanation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,sequence_id BIGINT NOT NULL AUTO_INCREMENT UNIQUE,prediction_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,context_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,context_json JSON NOT NULL,paragraphs_json JSON NOT NULL,created_at DATETIME(3) NOT NULL,UNIQUE KEY ux_explanation_context(prediction_id,context_hash),FOREIGN KEY(prediction_id) REFERENCES forecast_request(prediction_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE prediction_explanation_operation(operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,sequence_id BIGINT NOT NULL AUTO_INCREMENT UNIQUE,user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,prediction_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,context_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,context_json JSON NOT NULL,state VARCHAR(16) NOT NULL,explanation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,error_code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,created_at DATETIME(3) NOT NULL,lease_until DATETIME(3) NOT NULL,finished_at DATETIME(3) NULL,CHECK(state IN('RUNNING','SUCCEEDED','FAILED')),FOREIGN KEY(prediction_id) REFERENCES forecast_request(prediction_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE prediction_explanation_slot(slot_id TINYINT PRIMARY KEY,operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,lease_until DATETIME(3) NULL,CHECK(slot_id=1)) ENGINE=InnoDB;
INSERT INTO prediction_explanation_slot VALUES(1,NULL,NULL);
